"import sys
import os
sys.path.insert(0, os.path.abspath("."))
if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8")
from collections import Counter
import re
from scratch.batch7_audit.run_audit import analyze_dataset

dev = analyze_dataset("data/dev", "output.json")
fp_list = dev["false_positives"]

triggers = Counter()

for fp in fp_list:
    text = fp["message_text"]
    body_l = text.lower().strip()

    # Check trigger rules
    matched = []
    if re.search(r"\b(?:will|ill|i\'ll)\s+(?:revert|check|look|share|update|call|tell|get\s+back)\b", body_l):
        matched.append("Generic Acknowledgment ('will revert/call/check')")
    if re.search(r"\b(?:pls|please)\s+(?:call|ping|text|ring)\b", body_l):
        matched.append("Micro-communication request ('pls call/ping')")
    if re.search(r"\b(?:let\s+me\s+know|lmk|pls\s+lmk|please\s+let\s+me\s+know)\b", body_l):
        matched.append("Conversational scheduling probe ('let me know/lmk')")
    if re.search(r"\b(?:pls|please)\s+(?:pay|transfer|send\s+money)\b", body_l):
        matched.append("Domestic/petty payment request ('pls pay')")
    if re.search(r"\b(?:pls|please)\s+(?:order|buy|book|get)\b", body_l):
        matched.append("Domestic errand/purchase request ('pls buy/order/book')")
    if re.search(r"\b(?:can\s+we|could\s+we|shall\s+we)\s+(?:meet|connect|have\s+a\s+call|jump\s+on\s+a\s+call|do\s+a\s+call|sync)\b", body_l):
        matched.append("Meeting proposal probe ('can we meet/call')")
    if not matched:
        matched.append("Other directed request/commitment")

    for m in matched:
        triggers[m] += 1

print("--- False Positive Trigger Categories in Dev ---")
for cat, count in triggers.most_common():
    print(f"  {cat}: {count} ({count/len(fp_list)*100:.1f}%)")
"

